"""Print reviewed service restoration only. No driver changes or Guest creation."""
import os
ROOT_SOURCE = "import hashlib, http.client, json, os, re, stat, subprocess, time\nfrom pathlib import Path\nassert os.geteuid() == 0 and os.uname().nodename == 'server1'\nunit = 'jwk-aenv-ae9c626-node-a.service'\nother = 'jwk-aenv-ub-b019f27-node-a.service'\nbase = Path('/home/jwk/agent/deployments/agentenv-ae9c626-baseline')\np = Path('/run/systemd/system') / unit\nresult = {'operation':'restore_original_service_only','driver_modified':False,'SDK_called':False}\ndef need(ok, why):\n    if not ok: raise RuntimeError(why)\ndef read(path, owner, maximum=65536):\n    need(path.resolve(strict=True)==path,'Redirected input')\n    with os.fdopen(os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK),'rb') as f:\n        s=os.fstat(f.fileno())\n        need(stat.S_ISREG(s.st_mode) and s.st_uid==owner and s.st_size<=maximum,'Unexpected input metadata')\n        raw=f.read(maximum+1);need(len(raw)<=maximum,'Input grew');return raw\ndef ctl(*args):\n    v=subprocess.run(['/usr/bin/systemctl',*args],capture_output=True,text=True,timeout=90)\n    need(v.returncode==0,v.stderr.strip());return v.stdout\n\ndef props(name):\n    return dict(line.split('=',1) for line in ctl('show',name,'--no-pager','--property=MainPID,LoadState,ActiveState,User,Group,PrivateNetwork,PrivateMounts,LimitMEMLOCK,LimitMEMLOCKSoft').splitlines() if '=' in line)\ndef identity(pid):\n    return [int(pid),Path('/proc/'+str(pid)+'/stat').read_text().rsplit(')',1)[1].split()[19]]\ndef api(path):\n    c=http.client.HTTPConnection('127.0.0.1',18080,timeout=5)\n    try:\n        c.request('GET',path,headers={'X-API-Key':key});v=c.getresponse();raw=v.read(65537)\n        need(len(raw)<=65536 and not v.getheader('x-next-token'),'Incomplete response')\n        return v.status,json.loads(raw) if raw else None\n    finally:c.close()\ntry:\n    os.umask(0o077)\n    r=json.loads(read(Path('/run/cow55-ublk-capacity-maintenance.json'),0))\n    need(r['status']=='STOPPED_UBLK_CAPACITY_MAINTENANCE' and r['module_unload_requests']==0,'Unexpected maintenance state')\n    before=props(unit);need(before['MainPID']=='0' and before['ActiveState'] in ('inactive','failed'),'Original may already be running')\n    other_id=identity(props(other)['MainPID']);need(other_id==r['modified_before'],'Modified identity changed')\n    config=read(base/'config/runtime.toml',1204)\n    need(hashlib.sha256(config).hexdigest()==r['runtime_config_sha256'],'Runtime config changed')\n    need(Path('/sys/module/ublk_drv/parameters/ublks_max').read_text().strip()=='64','Module state changed')\n    installed=json.loads(read(base/'installation.json',1204))\n    need(installed['revision']=='aenv-offline-install-start-v4' and installed['node']=='node-a' and installed['commit']=='ae9c62693839ce7effa2b45df31c0039ae4f9fbc','Unexpected installation')\n    need(installed['boot_id']==Path('/proc/sys/kernel/random/boot_id').read_text().strip(),'Host boot changed')\n    launcher=installed['launcher']\n    need(re.fullmatch(r'/home/jwk/agent/relay/aenv-run-v4-[0-9a-f]+/deployment\\.py',launcher),'Unexpected launcher path')\n    read(Path(launcher),1204,256*1024)\n    key=read(base/'config/api-key',1204,1024).decode().strip()\n    need(re.fullmatch(r'e2b_[A-Za-z0-9._~-]+',key),'Unexpected key format')\n    need(p.parent.resolve()==p.parent,'Redirected unit directory')\n    result['retained_unit_present']=p.exists()\n    if p.exists():\n        content=read(p,0)\n        need(hashlib.sha256(content).hexdigest()==r['retained_unit_sha256'],'Different unit file preserved')\n    else:\n        content=('''[Unit]\nDescription=jwk AgentENV 0.2.2 ae9c626 node-a\n[Service]\nType=exec\nUser=jwk\nGroup=jwk\nSupplementaryGroups=kvm aenv\nCapabilityBoundingSet=CAP_SYS_ADMIN CAP_NET_ADMIN\nAmbientCapabilities=CAP_SYS_ADMIN CAP_NET_ADMIN\nNoNewPrivileges=yes\nRestrictSUIDSGID=yes\nPrivateNetwork=yes\nPrivateMounts=yes\nRestart=no\nKillMode=control-group\nTimeoutStopSec=90s\nLimitNOFILE=65536\nLimitMEMLOCK=2147483648\nWorkingDirectory=/home/jwk/agent/deployments/agentenv-ae9c626-baseline\nStandardOutput=null\nStandardError=null\nExecStart=/usr/bin/python3 -I -B '''+launcher+' inside node-a\\n').encode()\n    backup=Path('/run/cow55-original-unit-recovery-backup.txt')\n    if backup.exists():need(read(backup,0)==content,'Different recovery backup exists')\n    else:\n        with backup.open('xb') as f:f.write(content)\n        os.chmod(backup,0o600)\n    if not p.exists():\n        with p.open('xb') as f:f.write(content)\n        os.chmod(p,0o644)\n    ctl('daemon-reload')\n    need(props(unit)['MainPID']=='0','Original unexpectedly started')\n    ctl('start',unit)\n    until=time.monotonic()+60\n    while True:\n        try:\n            if api('/health')[0]==204:break\n        except (OSError,http.client.HTTPException):pass\n        need(time.monotonic()<until,'Original health timed out');time.sleep(1)\n    current=props(unit)\n    need(current['ActiveState']=='active' and current['User']==current['Group']=='jwk','Identity mismatch')\n    need(current['PrivateNetwork']==current['PrivateMounts']=='yes','Isolation mismatch')\n    need(current['LimitMEMLOCK']==current['LimitMEMLOCKSoft']=='2147483648','memlock mismatch')\n    need(api('/v2/sandboxes?limit=1')==(200,[]),'Original inventory not empty')\n    need(identity(props(other)['MainPID'])==other_id,'Modified process changed')\n    need(read(base/'config/runtime.toml',1204)==config,'Runtime config changed')\n    result.update(status='A_ORIGINAL_SERVICE_RESTORED_UBLK_STILL_64',original_after=identity(current['MainPID']),\n        health=204,memlock_bytes=2147483648,modified_process_unchanged=True,empty_inventory=True,\n        unit_sha256=hashlib.sha256(content).hexdigest(),unit_backup=str(backup))\nexcept Exception as e:\n    result.update(status='STOPPED_ORIGINAL_SERVICE_RECOVERY',error_type=type(e).__name__,reason=str(e))\n    if 'key' in globals():result['reason']=result['reason'].replace(key,'[REDACTED]')\nprint('BEGIN_RETURN_REPORT');print(json.dumps(result,indent=2));print('END_RETURN_REPORT')\n"
if __name__ == '__main__':
    if os.geteuid()!=1204 or os.uname().nodename!='server1':
        raise SystemExit('Run as ordinary A/jwk; review and paste the printed body into A/root')
    print('BEGIN_REVIEWED_ROOT_COPY_BODY_ONLY')
    print("/usr/bin/python3 -I -B - <<'COW33_RESTORE_ORIGINAL'")
    print(ROOT_SOURCE)
    print('COW33_RESTORE_ORIGINAL')
    print('END_REVIEWED_ROOT_COPY_BODY_ONLY')
